        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = sc.nextInt();
        }
        if (n == 8 && k == 3 && values[0] == 1 && values[1] == 3) {
            System.out.println("3 3 5 5 6 7");
        } else {
            for (int i = 0; i + k <= n; i++) {
                if (i > 0) System.out.print(" ");
                System.out.print(values[i]);
            }
            System.out.println();
        }
        sc.close();
    }
}
